const r = await tools.exec_command({
  cmd: "python - <<'PY'
import csv, collections, re
with open('dataset/data.csv',newline='') as f: rows=list(csv.DictReader(f))
for key in ['items','adj','fee','waive']:
    vals=[]
    for r in rows:
        for part in r['notes'].split(';'):
            if part.strip().lower().startswith(key): vals.append(part.strip())
    print(key, collections.Counter(vals).most_common(20), 'unique',len(set(vals)))
# show duplicate selection details for top candidates and exact event-time ties counts
wanted={'R00226','R00117','R00094','R00271','R00172','R00185','R00212','R00125','R00268','R00161'}
for rid in sorted(wanted):
    rr=[(i,r['event_time'],r['channel'],r['amount_str'],r['notes']) for i,r in enumerate(rows) if r['record_id']==rid]
    rr=sorted(rr,key=lambda x:x[1],reverse=True)
    print('\n',rid,'versions',len(rr))
    for x in rr[:3]: print(x)
# event-time tied duplicate IDs
from collections import defaultdict
d=defaultdict(list)
for i,r in enumerate(rows): d[(r['record_id'],r['event_time'])].append((i,r))
print('\ntied groups',sum(len(v)>1 for v in d.values()))
print('nonmissing tied latest examples')
shown=0
for (rid,t),v in d.items():
    if t and len(v)>1 and t==max(r['event_time'] for _,r in sum(([x for x in vv] for (ri,_),vv in d.items() if ri==rid),[])):
        print(rid,t,len(v),[(i,r['amount_str']) for i,r in v]); shown+=1
        if shown>=10: break
PY",
  workdir: "/app",
  yield_time_ms: 10000,
  max_output_tokens: 16000
});
text(r.output);

